#!/usr/bin/env bash
# GSZ step115 — storefront polish A1: footer payment chips removed, reviews
# heading reworded, review count floored. Safe + idempotent; restores on fail.
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step115-$TS"; TMP=$(mktemp -d)
FILES=(views/home.ejs views/partials/store_bottom.ejs)
echo "==> step115: home + footer polish"
mkdir -p "$BK"; for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/patch_step115.js"
echo "==> applying"; node "$TMP/patch_step115.js" "$GSZ"
echo "==> validating"; node -e "const ejs=require('$GSZ/node_modules/ejs');['views/home.ejs','views/partials/store_bottom.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
[ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
HP=$(curl -s http://127.0.0.1:3900/ || true)
grep -q 'Trusted by thousands of clients' <<<"$HP" && echo "    reviews heading updated: OK" || echo "    heading check: not found (non-fatal)"
grep -q 'class="pays"' <<<"$HP" && echo "    NOTE: footer pays still present" || echo "    footer payment chips removed: OK"
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step115 OK ✅  (footer payment chips removed · 'Trusted by thousands of clients' · review count floored)"
